def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    opp_reqs = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            opp_reqs.append(opp.get('water_requirement', WATER_REQ))
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(float(prev['bid']))

    if budget <= 0:
        return 0.0

    if not alive:
        if hp <= 2 or no_water_days >= 1:
            return float(min(budget, DAILY_SALARY * 0.55))
        return float(min(budget, DAILY_SALARY * 0.2))

    total_players = 1 + len(alive)
    total_req = WATER_REQ
    for r in opp_reqs:
        total_req += r

    scarcity_ratio = float(supply) / float(total_req) if total_req > 0 else 1.0
    expected_units = float(supply) / float(WATER_REQ) if WATER_REQ > 0 else 1.0
    pressure = total_players / expected_units if expected_units > 0 else total_players

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    urgent = hp <= 2 or no_water_days >= 1
    fragile = hp <= 4
    very_tight = scarcity_ratio < 0.32 or pressure > 2.6
    tight = scarcity_ratio < 0.42 or pressure > 2.0
    ample = scarcity_ratio > 0.55 and pressure < 1.5

    if urgent:
        if highest_prev > 0:
            bid = max(DAILY_SALARY * 0.95, highest_prev + 3.0)
        else:
            bid = DAILY_SALARY * 0.95
    elif very_tight:
        if fragile:
            bid = max(DAILY_SALARY * 0.88, highest_prev + 2.0 if highest_prev > 0 else DAILY_SALARY * 0.88)
        else:
            if highest_prev >= 120:
                bid = DAILY_SALARY * 0.28
            else:
                bid = max(DAILY_SALARY * 0.62, avg_prev + 1.5 if avg_prev > 0 else DAILY_SALARY * 0.62)
    elif tight:
        if highest_prev >= 130 and hp >= 5:
            bid = DAILY_SALARY * 0.3
        elif highest_prev > 0:
            bid = max(DAILY_SALARY * 0.52, min(highest_prev + 1.0, DAILY_SALARY * 1.55))
        else:
            bid = DAILY_SALARY * 0.55
    elif ample:
        if hp >= 5 and no_water_days == 0:
            bid = DAILY_SALARY * 0.18
        else:
            bid = DAILY_SALARY * 0.4
    else:
        if highest_prev > 0:
            bid = max(DAILY_SALARY * 0.42, min(avg_prev * 0.92, highest_prev + 0.5))
        else:
            bid = DAILY_SALARY * 0.48

    if day >= 8:
        if hp >= 5 and not urgent:
            bid *= 0.9
        else:
            bid *= 1.05

    reserve_floor = 0.0
    if day <= 7:
        reserve_floor = max(0.0, budget - DAILY_SALARY * (10 - int(day)))
        if bid > reserve_floor + DAILY_SALARY * 0.9:
            bid = reserve_floor + DAILY_SALARY * 0.9

    bid = max(0.0, min(float(budget), float(bid)))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    # Identify alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return min(budget, DAILY_SALARY * 0.4)

    # Read yesterday bids to infer aggressive pressure
    yesterday_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev.get('bid', 0.0)))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Supply pressure: higher supply means we can bid a bit less and still win
    # (but we don't know allocation rule; we use it as a conservative scaling)
    supply_ratio = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    if supply_ratio < 0.0:
        supply_ratio = 0.0
    if supply_ratio > 1.0:
        supply_ratio = 1.0

    # Base bid: aim around mid of daily salary, tempered by supply
    base = DAILY_SALARY * (0.45 + 0.15 * supply_ratio)

    # If my HP is low or I'm already accruing no-water days, increase bid to avoid death
    if hp <= 2:
        base = DAILY_SALARY * 0.9
    elif hp <= 4:
        base = DAILY_SALARY * 0.7

    if no_water_days >= 2:
        base = max(base, DAILY_SALARY * 0.65)

    # If yesterday saw very high bids, nudge upward slightly to compete.
    # Cindy/Eric were ~112-119; we don't want to match their full aggression unless necessary.
    if highest_prev_bid >= DAILY_SALARY * 1.15:
        if hp <= 4:
            target = max(base, highest_prev_bid * 0.75)
        else:
            target = max(base, highest_prev_bid * 0.55)
    elif highest_prev_bid >= DAILY_SALARY * 0.85:
        target = max(base, highest_prev_bid * 0.45)
    else:
        target = base

    # Never bid more than we can afford
    target = min(target, budget)

    # Also cap to avoid reckless spending (but allow above salary if budget permits)
    # In medium scenario supply is 15-25, so we can keep bids moderate.
    cap = DAILY_SALARY * 1.2
    target = min(target, cap)

    # If budget is extremely low, bid what we can
    if budget <= 1.0:
        return budget

    # Ensure non-negative
    if target < 0.0:
        target = 0.0

    return float(target)
